#requires -Version 5.1
$ErrorActionPreference='Stop'
$module=Import-Module (Join-Path $PSScriptRoot '..\src\WindowsServerMigration.psd1') -Force -PassThru
$root=Join-Path ([IO.Path]::GetTempPath()) ('wsm-assistive-rollback-'+[Guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($root)
try {
    & $module {
        param($root)
        function Check([bool]$condition,[string]$message){if(-not $condition){throw $message};$script:rollbackChecks++}
        function Get-MetadataFieldDiff($Expected,$Actual){$diff=New-Object 'System.Collections.Generic.List[string]';foreach($field in @('MetadataMode','Attributes','CreationUtc','LastWriteUtc')){if([string]$Expected.$field -cne [string]$Actual.$field){if($field -in @('CreationUtc','LastWriteUtc')){try{$expectedTime=[DateTimeOffset]::Parse([string]$Expected.$field);$actualTime=[DateTimeOffset]::Parse([string]$Actual.$field);$diff.Add(($field+' expected='+$expectedTime.ToUniversalTime().ToString('o')+' (ticks='+$expectedTime.UtcDateTime.Ticks+'), actual='+$actualTime.ToUniversalTime().ToString('o')+' (ticks='+$actualTime.UtcDateTime.Ticks+'), deltaTicks='+(($actualTime.UtcDateTime.Ticks)-($expectedTime.UtcDateTime.Ticks))))}catch{$diff.Add(($field+' expected/actual parse failed'))}}else{$diff.Add(($field+' expected='+[string]$Expected.$field+', actual='+[string]$Actual.$field))}}};if([string]$Expected.Sddl -cne [string]$Actual.Sddl){$diff.Add('Sddl=<changed; value redacted>')};if($diff.Count){return ($diff -join '; ')};return 'none'}
        function Add-WsmJournal($Paths,$State,[string]$Action,[string]$ItemId,$Detail){$script:rollbackJournal+=@($Action)}
        $script:rollbackChecks=0;$script:rollbackJournal=@()
        $itemId='0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef'
        $target=Join-Path $root 'scope';$nested=Join-Path $target 'nested';$empty=Join-Path $target 'empty'
        [void][IO.Directory]::CreateDirectory($nested);[void][IO.Directory]::CreateDirectory($empty)
        $external=Join-Path $target 'operator.txt';[IO.File]::WriteAllText($external,'operator-owned')
        $file=Join-Path $nested 'settings.ini';$backup=$file+'.wsm-assistive-backup-'+$itemId.Substring(0,12)+'-'+[Guid]::NewGuid().ToString('N')
        [IO.File]::WriteAllText($file,'new-generation');[IO.File]::WriteAllText($backup,'prior-generation')
        $fileHash=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant();$backupHash=(Get-FileHash -LiteralPath $backup -Algorithm SHA256).Hash.ToLowerInvariant()
        $priorDirectoryMetadata=Get-WsmFileMetadata $nested 'DaclOwner'
        $changedDirectoryMetadata=$priorDirectoryMetadata.PSObject.Copy();$changedDirectoryMetadata.LastWriteUtc=([DateTime]::UtcNow.AddMinutes(-3).ToString('o'));Set-WsmFileMetadata $nested $changedDirectoryMetadata @{};$currentDirectoryMetadata=Get-WsmFileMetadata $nested 'DaclOwner'
        # Capture file baselines only after all directory metadata/ACL setup is complete. Set-Acl on a parent can propagate inherited ACEs to children.
        $fileMetadata=Get-WsmFileMetadata $file 'DaclOwner';$backupMetadata=Get-WsmFileMetadata $backup 'DaclOwner'
        $rootMetadata=Get-WsmFileMetadata $target 'DaclOwner';$emptyMetadata=Get-WsmFileMetadata $empty 'DaclOwner'
        $record=[pscustomobject]@{ItemId=$itemId;Status='Succeeded';CreatedByTool=$true;Target=$target;OwnedFiles=@([pscustomobject]@{RelativePath='nested\settings.ini';TargetPath=$file;SHA256=$fileHash;MetadataHash=(Get-WsmAssistiveMetadataHash $fileMetadata);Backup=$backup;BackupHash=$backupHash;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $backupMetadata);Generation=2});OwnedDirectories=@([pscustomobject]@{RelativePath='nested';TargetPath=$nested;MetadataHash=(Get-WsmAssistiveMetadataHash $currentDirectoryMetadata);BackupMetadata=$priorDirectoryMetadata;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $priorDirectoryMetadata);CreatedByTool=$false;Generation=2},[pscustomobject]@{RelativePath='empty';TargetPath=$empty;MetadataHash=(Get-WsmAssistiveMetadataHash $emptyMetadata);BackupMetadata=$null;BackupMetadataHash='';CreatedByTool=$true;Generation=2},[pscustomobject]@{RelativePath='';TargetPath=$target;MetadataHash=(Get-WsmAssistiveMetadataHash $rootMetadata);BackupMetadata=$null;BackupMetadataHash='';CreatedByTool=$true;Generation=2})}
        $state=[pscustomobject]@{Items=@($record);PendingOperations=@()};$paths=[pscustomobject]@{Root=$root;State='';Journal=''};$spec=[pscustomobject]@{Adapter='FileScope';TargetPath=$target;Metadata='DaclOwner'};$item=[pscustomobject]@{ItemId=$itemId;MigrationSpec=$spec}
        $action=[pscustomobject]@{RelativePath='nested\settings.ini';TargetPath=$file;Retained=(Join-Path $nested ('.wsm-assistive-rollback-'+[Guid]::NewGuid().ToString('N')));CurrentHash=$fileHash;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $fileMetadata);Backup=$backup;BackupHash=$backupHash;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $backupMetadata);BackupMetadata=$backupMetadata}
        $operation=[pscustomobject]@{ItemId=$itemId;Phase='RollbackAssistiveFiles';ManifestHash=('a'*64);Target=$target;Files=@($action);Directories=@([pscustomobject]@{RelativePath='nested';TargetPath=$nested;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $currentDirectoryMetadata);CurrentMetadata=$currentDirectoryMetadata;BackupMetadata=$priorDirectoryMetadata;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $priorDirectoryMetadata);CreatedByTool=$false},[pscustomobject]@{RelativePath='empty';TargetPath=$empty;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $emptyMetadata);CurrentMetadata=$emptyMetadata;BackupMetadata=$null;BackupMetadataHash='';CreatedByTool=$true},[pscustomobject]@{RelativePath='';TargetPath=$target;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $rootMetadata);CurrentMetadata=$rootMetadata;BackupMetadata=$null;BackupMetadataHash='';CreatedByTool=$true})}
        try{Complete-WsmAssistiveFileRollback $item $operation $paths $state}catch{$failure=$_.Exception.Message;$currentFileMetadata=Get-WsmFileMetadata $file 'DaclOwner';$currentNestedMetadata=Get-WsmFileMetadata $nested 'DaclOwner';throw ('Baseline rollback rejected unexpectedly; file vs prior backup fields='+(Get-MetadataFieldDiff $backupMetadata $currentFileMetadata)+'; nested vs prechange prior-directory fields='+(Get-MetadataFieldDiff $priorDirectoryMetadata $currentNestedMetadata)+'; nested vs reviewed current-directory fields='+(Get-MetadataFieldDiff $currentDirectoryMetadata $currentNestedMetadata)+'; cause='+$failure)}
        Check ([IO.File]::ReadAllText($file) -ceq 'prior-generation') 'Rollback did not restore the exact prior per-file backup.'
        Check (-not [IO.File]::Exists($backup) -and [IO.File]::Exists($action.Retained)) 'Rollback did not retain displaced current bytes or consume the verified prior backup.'
        Check ([IO.File]::ReadAllText($external) -ceq 'operator-owned') 'Rollback removed or replaced unowned external content in the merged root.'
        Check (-not [IO.Directory]::Exists($empty)) 'Rollback did not remove an empty directory created by the tool.'
        Check ((Get-WsmAssistiveMetadataHash (Get-WsmFileMetadata $nested 'DaclOwner')) -ceq (Get-WsmAssistiveMetadataHash $priorDirectoryMetadata)) 'Rollback did not restore and read back prior owned-directory metadata.'
        Check ($record.Status -ceq 'RolledBack' -and -not $record.CreatedByTool) 'Per-file rollback did not retire the generation ownership record.'
        Complete-WsmAssistiveFileRollback $item $operation $paths $state
        Check ([IO.File]::ReadAllText($file) -ceq 'prior-generation') 'Interrupted rollback replay was not idempotent after the prior backup move.'

        # Mixed-generation ownership evidence: the prior file backup inherits from ACL B,
        # while the directory prior snapshot is ACL A. File restore/readback is valid under B;
        # applying A afterward propagates a different ACL to the restored child.
        $mixedRoot=Join-Path $root 'mixed-parent-file';$mixedNested=Join-Path $mixedRoot 'nested';[void][IO.Directory]::CreateDirectory($mixedNested)
        $dirA=Join-Path $root 'mixed-dir-a';[void][IO.Directory]::CreateDirectory($dirA);$mixedPriorDirectoryMetadata=Get-WsmFileMetadata $dirA 'DaclOwner'
        $mixedAcl=Get-Acl -LiteralPath $mixedNested;$mixedEveryone=New-Object Security.Principal.SecurityIdentifier('S-1-1-0');$mixedFlags=[Security.AccessControl.InheritanceFlags]([int][Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [int][Security.AccessControl.InheritanceFlags]::ObjectInherit);$mixedRule=[Security.AccessControl.FileSystemAccessRule]::new($mixedEveryone,[Security.AccessControl.FileSystemRights]::Read,$mixedFlags,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow);[void]$mixedAcl.AddAccessRule($mixedRule);Set-Acl -LiteralPath $mixedNested -AclObject $mixedAcl
        $mixedFile=Join-Path $mixedNested 'settings.ini';$mixedBackup=$mixedFile+'.wsm-assistive-backup-'+$itemId.Substring(0,12)+'-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($mixedFile,'current-generation');[IO.File]::WriteAllText($mixedBackup,'prior-generation')
        $mixedCurrentHash=(Get-FileHash -LiteralPath $mixedFile -Algorithm SHA256).Hash.ToLowerInvariant();$mixedPriorHash=(Get-FileHash -LiteralPath $mixedBackup -Algorithm SHA256).Hash.ToLowerInvariant();$mixedCurrentMetadata=Get-WsmFileMetadata $mixedFile 'DaclOwner';$mixedBackupMetadata=Get-WsmFileMetadata $mixedBackup 'DaclOwner';$mixedCurrentDirectoryMetadata=Get-WsmFileMetadata $mixedNested 'DaclOwner'
        $mixedRetained=Join-Path $mixedNested ('.wsm-assistive-rollback-'+[Guid]::NewGuid().ToString('N'))
        $mixedRecord=[pscustomobject]@{ItemId=$itemId;Status='Succeeded';CreatedByTool=$true;Target=$mixedRoot;OwnedFiles=@();OwnedDirectories=@()};$mixedState=[pscustomobject]@{Items=@($mixedRecord);PendingOperations=@()};$mixedItem=[pscustomobject]@{ItemId=$itemId;MigrationSpec=[pscustomobject]@{Adapter='FileScope';TargetPath=$mixedRoot;Metadata='DaclOwner'}}
        $mixedFileAction=[pscustomobject]@{RelativePath='nested\settings.ini';TargetPath=$mixedFile;Retained=$mixedRetained;CurrentHash=$mixedCurrentHash;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $mixedCurrentMetadata);Backup=$mixedBackup;BackupHash=$mixedPriorHash;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $mixedBackupMetadata);BackupMetadata=$mixedBackupMetadata}
        $mixedDirectory=[pscustomobject]@{RelativePath='nested';TargetPath=$mixedNested;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $mixedCurrentDirectoryMetadata);CurrentMetadata=$mixedCurrentDirectoryMetadata;BackupMetadata=$mixedPriorDirectoryMetadata;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $mixedPriorDirectoryMetadata);CreatedByTool=$false}
        $mixedOperation=[pscustomobject]@{ItemId=$itemId;Phase='RollbackAssistiveFiles';ManifestHash=('c'*64);Target=$mixedRoot;Files=@($mixedFileAction);Directories=@($mixedDirectory)}
        $mixedRejected=$false;$mixedError='';try{Complete-WsmAssistiveFileRollback $mixedItem $mixedOperation $paths $mixedState}catch{$mixedRejected=$true;$mixedError=$_.Exception.Message}
        $mixedFinalMetadata=Get-WsmFileMetadata $mixedFile 'DaclOwner';$mixedFinalHash=Get-WsmAssistiveMetadataHash $mixedFinalMetadata;$mixedPriorMetadataHash=Get-WsmAssistiveMetadataHash $mixedBackupMetadata
        Write-Host ('REPRO mixed rollback: rejected='+$mixedRejected+'; error='+$mixedError+'; status='+$mixedRecord.Status+'; backup metadata hash='+$mixedPriorMetadataHash+'; final file metadata hash='+$mixedFinalHash+'; final directory metadata fields vs prior='+ (Get-MetadataFieldDiff $mixedPriorDirectoryMetadata (Get-WsmFileMetadata $mixedNested 'DaclOwner')))
        Check ([IO.File]::ReadAllText($mixedFile) -ceq 'prior-generation') 'Mixed-generation rollback did not restore exact prior file bytes.'
        Check ($mixedRejected -or $mixedRecord.Status -cne 'RolledBack' -or $mixedFinalHash -ceq $mixedPriorMetadataHash) 'Rollback marked a child file RolledBack although restoring the prior parent ACL changed the child metadata after its last readback.'

        # Coherent replay: the prior directory snapshot has ACL A, while the current owned
        # directory has ACL B. No files are present, so this isolates the exact directory
        # metadata replay state without file-inheritance generation differences. First rollback restores A exactly;
        # replay must accept the complete prior metadata hash before comparing current B.
        $replayRoot=Join-Path $root 'directory-replay';$replayDirectory=Join-Path $replayRoot 'nested';[void][IO.Directory]::CreateDirectory($replayDirectory)
        $priorSource=Join-Path $root 'directory-replay-prior-a';[void][IO.Directory]::CreateDirectory($priorSource);$replayPriorMetadata=Get-WsmFileMetadata $priorSource 'DaclOwner'
        $currentAcl=Get-Acl -LiteralPath $replayDirectory;$replayEveryone=New-Object Security.Principal.SecurityIdentifier('S-1-1-0');$replayFlags=[Security.AccessControl.InheritanceFlags]([int][Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [int][Security.AccessControl.InheritanceFlags]::ObjectInherit);$replayRule=[Security.AccessControl.FileSystemAccessRule]::new($replayEveryone,[Security.AccessControl.FileSystemRights]::Read,$replayFlags,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow);[void]$currentAcl.AddAccessRule($replayRule);Set-Acl -LiteralPath $replayDirectory -AclObject $currentAcl;$replayCurrentMetadata=Get-WsmFileMetadata $replayDirectory 'DaclOwner'
        $replayRecord=[pscustomobject]@{ItemId=$itemId;Status='Succeeded';CreatedByTool=$true;Target=$replayRoot;OwnedFiles=@();OwnedDirectories=@()};$replayState=[pscustomobject]@{Items=@($replayRecord);PendingOperations=@()};$replayItem=[pscustomobject]@{ItemId=$itemId;MigrationSpec=[pscustomobject]@{Adapter='FileScope';TargetPath=$replayRoot;Metadata='DaclOwner'}};$replayOperation=[pscustomobject]@{ItemId=$itemId;Phase='RollbackAssistiveFiles';ManifestHash=('d'*64);Target=$replayRoot;Files=@();Directories=@([pscustomobject]@{RelativePath='nested';TargetPath=$replayDirectory;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $replayCurrentMetadata);CurrentMetadata=$replayCurrentMetadata;BackupMetadata=$replayPriorMetadata;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $replayPriorMetadata);CreatedByTool=$false})}
        Complete-WsmAssistiveFileRollback $replayItem $replayOperation $paths $replayState
        Check ($replayRecord.Status -ceq 'RolledBack' -and (Get-WsmAssistiveMetadataHash (Get-WsmFileMetadata $replayDirectory 'DaclOwner')) -ceq (Get-WsmAssistiveMetadataHash $replayPriorMetadata)) 'First directory-only rollback did not restore exact prior metadata.'
        $replayRejected=$false;$replayError='';try{Complete-WsmAssistiveFileRollback $replayItem $replayOperation $paths $replayState}catch{$replayRejected=$true;$replayError=$_.Exception.Message}
        Check (-not $replayRejected -and $replayRecord.Status -ceq 'RolledBack' -and (Get-WsmAssistiveMetadataHash (Get-WsmFileMetadata $replayDirectory 'DaclOwner')) -ceq (Get-WsmAssistiveMetadataHash $replayPriorMetadata)) ('Exact prior directory metadata was not accepted on rollback replay; error='+$replayError+'; expected fields='+ (Get-MetadataFieldDiff $replayPriorMetadata (Get-WsmFileMetadata $replayDirectory 'DaclOwner')))

        $driftRoot=Join-Path $root 'drift';[void][IO.Directory]::CreateDirectory($driftRoot);$driftFile=Join-Path $driftRoot 'owned.bin';[IO.File]::WriteAllText($driftFile,'operator drift')
        $driftHash=(Get-FileHash -LiteralPath $driftFile -Algorithm SHA256).Hash.ToLowerInvariant();$driftMetadata=Get-WsmFileMetadata $driftFile 'DaclOwner';$driftRecord=[pscustomobject]@{ItemId=$itemId;Status='Succeeded';CreatedByTool=$true};$driftState=[pscustomobject]@{Items=@($driftRecord);PendingOperations=@()};$driftItem=[pscustomobject]@{ItemId=$itemId;MigrationSpec=[pscustomobject]@{Adapter='FileScope';TargetPath=$driftRoot;Metadata='DaclOwner'}};$driftAction=[pscustomobject]@{RelativePath='owned.bin';TargetPath=$driftFile;Retained=(Join-Path $driftRoot ('.wsm-assistive-rollback-'+[Guid]::NewGuid().ToString('N')));CurrentHash=('f'*64);CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $driftMetadata);Backup='';BackupHash='';BackupMetadataHash=''};$driftOperation=[pscustomobject]@{ItemId=$itemId;Phase='RollbackAssistiveFiles';ManifestHash=('a'*64);Target=$driftRoot;Files=@($driftAction);Directories=@()}
        $rejected=$false;try{Complete-WsmAssistiveFileRollback $driftItem $driftOperation $paths $driftState}catch{$rejected=$true}
        Check $rejected 'Rollback accepted bytes that drifted from the exact owned generation.'
        Check ([IO.File]::ReadAllText($driftFile) -ceq 'operator drift' -and -not [IO.File]::Exists($driftAction.Retained)) 'Rejected rollback modified or displaced drifted target data.'

        # A real parent ACL change with inheritable ACEs must change the child file metadata and keep rollback fail-closed.
        $propRoot=Join-Path $root 'acl-propagation';$propNested=Join-Path $propRoot 'nested';[void][IO.Directory]::CreateDirectory($propNested)
        $propFile=Join-Path $propNested 'owned.txt';[IO.File]::WriteAllText($propFile,'owned generation');$propBackup=$propFile+'.wsm-assistive-backup-'+$itemId.Substring(0,12)+'-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($propBackup,'prior generation')
        $propCurrentHash=(Get-FileHash -LiteralPath $propFile -Algorithm SHA256).Hash.ToLowerInvariant();$propBackupHash=(Get-FileHash -LiteralPath $propBackup -Algorithm SHA256).Hash.ToLowerInvariant()
        $propRootMetadata=Get-WsmFileMetadata $propRoot 'DaclOwner';$propDirectoryBefore=Get-WsmFileMetadata $propNested 'DaclOwner';$propFileBefore=Get-WsmFileMetadata $propFile 'DaclOwner';$propBackupMetadata=Get-WsmFileMetadata $propBackup 'DaclOwner'
        $propRetained=Join-Path $propNested ('.wsm-assistive-rollback-'+[Guid]::NewGuid().ToString('N'))
        $propOperation=[pscustomobject]@{ItemId=$itemId;Phase='RollbackAssistiveFiles';ManifestHash=('b'*64);Target=$propRoot;Files=@([pscustomobject]@{RelativePath='nested\owned.txt';TargetPath=$propFile;Retained=$propRetained;CurrentHash=$propCurrentHash;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $propFileBefore);Backup=$propBackup;BackupHash=$propBackupHash;BackupMetadataHash=(Get-WsmAssistiveMetadataHash $propBackupMetadata);BackupMetadata=$propBackupMetadata});Directories=@([pscustomobject]@{RelativePath='nested';TargetPath=$propNested;CurrentMetadataHash=(Get-WsmAssistiveMetadataHash $propDirectoryBefore);CurrentMetadata=$propDirectoryBefore;BackupMetadata=$null;BackupMetadataHash='';CreatedByTool=$true})}
        $propAcl=Get-Acl -LiteralPath $propNested;$everyone=New-Object Security.Principal.SecurityIdentifier('S-1-1-0');$inheritance=[Security.AccessControl.InheritanceFlags]([int][Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [int][Security.AccessControl.InheritanceFlags]::ObjectInherit);$inheritableRule=[Security.AccessControl.FileSystemAccessRule]::new($everyone,[Security.AccessControl.FileSystemRights]::Read,$inheritance,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow);[void]$propAcl.AddAccessRule($inheritableRule);Set-Acl -LiteralPath $propNested -AclObject $propAcl
        $propFileAfter=Get-WsmFileMetadata $propFile 'DaclOwner';$propDirectoryAfter=Get-WsmFileMetadata $propNested 'DaclOwner'
        Check ((Get-WsmAssistiveMetadataHash $propFileBefore) -cne (Get-WsmAssistiveMetadataHash $propFileAfter)) ('Parent ACL propagation fixture did not alter child metadata; child field differences='+(Get-MetadataFieldDiff $propFileBefore $propFileAfter))
        $propState=[pscustomobject]@{Items=@([pscustomobject]@{ItemId=$itemId;Status='Succeeded';CreatedByTool=$true});PendingOperations=@()};$propItem=[pscustomobject]@{ItemId=$itemId;MigrationSpec=[pscustomobject]@{Adapter='FileScope';TargetPath=$propRoot;Metadata='DaclOwner'}};$propPaths=[pscustomobject]@{Root=$root;State='';Journal=''}
        $propRejected=$false;$propError='';try{Complete-WsmAssistiveFileRollback $propItem $propOperation $propPaths $propState}catch{$propRejected=$true;$propError=$_.Exception.Message}
        Check $propRejected ('Rollback accepted parent-propagated child ACL drift; expected child fields='+ (Get-MetadataFieldDiff $propFileBefore $propFileAfter)+'; directory fields='+(Get-MetadataFieldDiff $propDirectoryBefore $propDirectoryAfter))
        Check ([IO.File]::ReadAllText($propFile) -ceq 'owned generation' -and [IO.File]::Exists($propBackup) -and -not [IO.File]::Exists($propOperation.Files[0].Retained)) ('Parent ACL drift rejection modified rollback bytes; rejection='+$propError)
        Write-Host ('PASS: '+$script:rollbackChecks+' Assistive per-file rollback checks.')
    } $root
} finally {Remove-Item -LiteralPath $root -Recurse -Force}
